"""Table tennis (the twins of PR #154 are generated by tools/tt_fullsim; this adapter is the generic reference and is
used by the generic tests and calibrate.py)."""

EXPORT = False  # the table-tennis twins come from tools/tt_fullsim (PR #154)
SPORT = "tabletennis"
SOURCE_TASK = "tabletennis-match-wallclock-program-standard"
FAMILY = "tabletennis-match"
INSTANCES = {"i01": {"level": 2, "seed": 22}, "i02": {"level": 3, "seed": 12}}
SLOWDOWN = 10
CUTOFF_S = 7200
READY_TIMEOUT_S = 300
MATCH_WALL_S = 1800
IMAGE = "ghcr.io/mll-lab-nu/eai-olympiad:0.1.0@sha256:99255569bf68bcf27f4e4867b58bad55c1d54fe73281920882e97c310836b6c7"


def truth(match):
    r = match.R
    return {
        **r.s.state(),
        "opponent_x": r.opp_x(),
        "opponent_parameters": r.lv,
        "leg": r.leg,
        "qpos": r.s.d.qpos,
        "qvel": r.s.d.qvel,
        "servo": r.s.servo.state(),
    }
